import uiautomation as auto
auto.SetGlobalSearchTimeout(2)
root=auto.ControlFromHandle(462320)
print("ROOT",root.Name)
tests=[
    ("address", lambda: root.EditControl(Name="Address and search bar", searchDepth=8)),
    ("doc", lambda: root.DocumentControl(searchDepth=8)),
]
for label,fn in tests:
    try:
        c=fn()
        print(label,"EXISTS",c.Exists(0,0))
        if c.Exists(0,0):
            print(label,"NAME",repr(c.Name),"AID",repr(c.AutomationId),"CLASS",repr(c.ClassName),"VALUE",repr(c.GetValuePattern().Value if c.GetValuePattern() else None))
            kids=c.GetChildren()
            print(label,"KIDS",len(kids))
            for k in kids[:40]:
                print(" ",k.ControlTypeName,repr(k.Name),repr(k.AutomationId),repr(k.ClassName))
    except Exception as e:
        print(label,"ERR",repr(e))
